276		}
277		report := decodeReport(t, stdout)
278		got := report.Rules[0]
279		if got.ID != id || got.Severity != severity || got.Invariant != invariant || got.Version != " v1\n " {
280			t.Fatalf("rule text must be preserved verbatim:\n%+v", got)
281		}
282		readStdout, _, readCode := runCLIReport(t, bin, store, report.ReportID)
283		if readCode != 0 {
284			t.Fatal("the saved report must read back by id")
285		}
286		loaded := decodeReport(t, readStdout)
287		if loaded.ReportID != report.ReportID || loaded.Rules[0] != report.Rules[0] {
