292	// jsonCLIString quotes a Go string as a JSON string literal for hand-built input.
293	func jsonCLIString(s string) string {
294		b := strings.Builder{}
295		b.WriteByte('"')
296		for _, r := range s {
297			switch r {
298			case '"':
299				b.WriteString(`\"`)
300			case '\\':
301				b.WriteString(`\\`)
302			case '\n':
303				b.WriteString(`\n`)
304			case '\t':
305				b.WriteString(`\t`)
306			default:
307				b.WriteRune(r)
308			}
309		}
310		b.WriteByte('"')
311		return b.String()
312	}
